ROUND((400000 / NULLIF(pld.perfect_work_days, 0)) * pld.paid_leave_days, 0) ELSE ROUND((400000 / NULLIF(pld.perfect_work_days, 0)) * pld.paid_leave_days, 0) END) END AS deduct_transport_amount , ROUND(pld.extra_hours * ROUND(pld.base_salary / 192, 0) * 1.5, 0) AS actual_extra_hour_amount , -ROUND((250000 / NULLIF(pld.perfect_work_hours, 0) * pld.paid_leave_hours), 0) AS deduct_att_incentive , (CASE WHEN ROUND((250000 / NULLIF(pld.perfect_work_hours, 0) * pld.paid_leave_hours), 0) = 0 THEN 0 ELSE pld.attendance_incentive_base - ROUND((250000 / NULLIF(pld.perfect_work_hours, 0) * pld.paid_leave_hours), 0) END) AS deduct_att_incentive_amt , -ROUND((pld.menstruation_base / NULLIF(pld.perfect_work_hours, 0)) * pld.paid_leave_hours, 0) AS menstruation_adjustment , ROUND(pld.menstruation_base + (-ROUND((pld.menstruation_base / NULLIF(pld.perfect_work_hours, 0)) * pld.paid_leave_hours, 0)), 0) AS menstruation_up_manual
FROM TB_PAY_PAID_LEAVE_DETAIL_N pld WHERE pld.payment_yyyymm = #{payMonth}
AND pld.employee_no = #{employeeNo}
ORDER BY pld.EMPLOYEE_NO

